	},
})

Translate("zhCN", "zephras-isle", {
	title = "泽弗拉斯岛",
	aliases = { "泽弗拉斯" },
	sections = {
		{
			title = "概述",
			text = [=[泽弗拉斯岛漂浮在{link:skywall}天空之墙{/link}，空气的领域之中，远离{link:azeroth}艾泽拉斯{/link}的任何海岸。它是{link:skyborne}天裔{/link}的家园，这些精灵自称申多雷。巨树高耸在北部的{link:moonglade}林地{/link}上，蓝色的{link:razorfen-downs}高地{/link}在岛的中部起伏，东南边缘矗立着港口{link:valanaar}瓦兰纳尔{/link}。瀑布从悬崖上倾泻而下，落入开阔的天空。一万年来，这座岛是一处隐秘的避难所。如今它正在分崩离析，它的人民开始向下张望，望向一个他们的祖先曾经逃离的世界。]=],
		},
		{
			title = "起源",
			text = [=[{link:skyborne}申多雷{/link}是埃德{link:farmer-ray}雷{/link}·萨拉斯叛乱者的后裔，埃德雷·萨拉斯是{link:feralas}菲拉斯{/link}的上层精灵之城，如今被称为{red:dire-maul}厄运之槌{/red}。他们起来反抗{red:tortheldrin}托塞德林{/red}王子，输掉了战争，并向西渡海逃亡。当王子的船队逼近时，{link:vanishing-of-the-wind-spirits}风之灵{/link}把一大片土地升上天空，带离了这个世界。它们用古老的{link:anchor-pylons}锚定塔{/link}把它固定在{link:skywall}天空之墙{/link}中，流亡者们在那里的云层之间建立了一个小而明亮的文明。它的创立者，那位被称为{link:flight-from-eldre-thalas}沙尔南{/link}的蒙面叛乱者，后来把自己的权力交给了一个由人民推选的{link:shadow-council}议会{/link}。]=],
		},
		{
			title = "当今",
			text = [=[几个世纪前，{link:vanishing-of-the-wind-spirits}风之灵{/link}一声不响地消失了。从那以后，{link:anchor-pylons}锚定塔{/link}日渐衰弱，整片整片的街区崩塌，落入天空。{link:ruins-of-ban-aethal}班埃索尔{/link}在一夜之间坠落。与{link:skyborne}申多雷{/link}其他岛屿的联系已经中断，逃到泽弗拉斯的难民如今挤满了{link:valanaar}瓦兰纳尔{/link}，或沦为盗匪。就在这样的恐惧之中，{link:al-aketh}奥拉凯斯{/link}出现了，这是一个崇拜{link:al-akir}奥拉基尔{/link}的教派，由{link:high-priestess-lorthuna}大祭司洛苏娜{/link}领导。他们夺取了{link:falaath-village}法拉斯村{/link}和{link:shrine-of-akir}阿基尔神殿{/link}，并袭击了锚定塔的瞭望塔。他们的目的是打破隐藏这座岛的结界。{link:windshapers}塑风者{/link}与{link:high-order}至高教团{/link}彼此鄙视，但他们与{link:valennia-stormfist}瓦伦妮娅·风暴之拳{/link}的{link:peacekeepers}维和者{/link}站在一起对抗这个教派，教派被击溃了。它的作为却没有。结界已经消失，风王麾下的一位领主已经看见了泽弗拉斯。如今两个组织各自把年轻人送往{link:azeroth}艾泽拉斯{/link}：塑风者前往{link:mulgore}莫高雷{/link}的{link:earthen-ring}大地之环{/link}，至高教团前往{link:dalaran}达拉然{/link}的{link:kirin-tor}肯瑞托{/link}。]=],
		},
		{
			title = "居民",
			text = [=[• {b}长老{link:shadow-council}议会{/link}。{/b} 大长老{link:talaanis-shadowsong}塔兰尼斯·影歌{/link}在{link:valanaar}瓦兰纳尔{/link}领导岛上的议会。
• {b}{link:windshapers}塑风者{/link}。{/b} 守护{link:senator-mehr-stonehallow}圣石{/link}、寻找消失的灵魂的萨满祭司与先知。
• {b}{link:high-order}至高教团{/link}。{/b} 拥有上层精灵血统、想要亲自掌控岛上魔法的魔导师。
• {b}{link:peacekeepers}维和者{/link}。{/b} 岛上的民兵，{link:skyborne}申多雷{/link}最接近军队的存在。
• {b}{link:al-aketh}奥拉凯斯{/link}。{/b} {link:al-akir}风王{/link}的狂热信徒，已被打散，却未被消灭。
• {b}夜爪。{/b} {link:shadowgale-forest}影风森林{/link}中一个隐秘的德鲁伊团体。
• {b}野兽。{/b} 沃尔德伦、乌瑟拉、傲爪兽、角鹰兽和尖啸兽，自从风沉寂以来，许多都变得狂野。]=],
		},
		{
			title = "岛屿的传说",
			text = [=[• 一个成年的{link:skyborne}申多雷{/link}会得到一件传家宝，那曾由一位前人携带。当持有者死去，传家宝会被收回，留给下一个年轻人。
• 死者会被火化，他们的骨灰交给风。
• 风之石是充满原始之风的蓝色宝石，如今为岛上大多数家庭提供光和热。
• 小小的记忆水晶能保存声音。触碰它们，录下的声音便会在空气中微弱地飘出。]=],
		},
	},
})

Translate("zhCN", "thendal-village", {
	title = "森达尔村",
	aliases = { "森达尔林地" },
	sections = {
		{
			title = "概述",
			text = [=[森达尔村位于{link:zephras-isle}泽弗拉斯{/link}北部的{link:moonglade}林地{/link}中，年轻的{link:skyborne}申多雷{/link}在这里成年。村里的房屋建在一棵巨大的祖父树之中及其周围，村里的游侠维持着林地的平衡。{link:rorian-the-dayseeker}寻日者罗里安{/link}领导着这个村庄。{link:shadow-council}议会{/link}的长老们来到这里评判年轻人，并把他们派往岛上各处。村子以东矗立着森{link:dar}达尔{/link}立石，那是一个风与魔网线交汇之地。沿着一条山口向东北而上是众灵{link:razorfen-downs}高地{/link}，{link:windshapers}塑风者{/link}见习者在那里饮用神圣的萨普塔。乌瑟拉在南边的一个洞穴里筑巢。最近，教派甚至来到了这里。]=],
		},
	},
})

Translate("zhCN", "shen-dar-village", {
	title = "辛达尔村",
	sections = {
		{
			title = "概述",
			text = [=[辛达尔村是北部{link:moonglade}林地{/link}以南的第一个城镇，坐落在{link:shen-dar-highlands}辛达尔高地{/link}的蓝色山丘之中。{link:constable-aonda}治安官奥恩达{/link}带着太少的{link:peacekeepers}维和者{/link}维持着这里的治安。两个组织在这里都有长老：{link:windshapers}塑风者{/link}的{link:illaya-amberwind}伊莱娅·琥珀之风{/link}和{link:high-order}至高教团{/link}的{link:rathiril-sunlance}拉希瑞尔·阳矛{/link}，他们在很多事情上意见不合。科瑞拉·静风经营着旅店。有一段时间，村子容忍一名{link:al-aketh}奥拉凯斯{/link}传教士在街上活动。当教派在法拉斯集结准备袭击村庄时，这份平静结束了，村民们先发制人。]=],
		},
	},
})

Translate("zhCN", "shen-dar-highlands", {
	title = "辛达尔高地",
	sections = {
		{
			title = "概述",
			text = [=[辛达尔高地是{link:zephras-isle}泽弗拉斯{/link}起伏的中心地带。这里的立石对{link:windshapers}塑风者{/link}来说是神圣的，他们守护着这些立石，提防{link:high-order}至高教团{/link}好奇的魔导师。两个组织之间曾在那些立石旁流过血。盗匪藏在北面一道瀑布后的洞穴里，角鹰兽在南面筑巢，傲爪兽在村子附近潜行。在{link:razorfen-downs}高地{/link}{link:anchor-pylons}锚定塔{/link}附近的一座山丘上，住着一个淘气的古老森林之灵库拉玛。有翼的沃尔德伦沃尔加拉在山丘中狩猎，{link:peacekeepers}维和者{/link}已悬赏她的首级。]=],
		},
	},
})

Translate("zhCN", "falaath-village", {
	title = "法拉斯村",
	sections = {
		{
			title = "概述",
			text = [=[法拉斯村是{link:shen-dar-highlands}辛达尔高地{/link}中的一片废墟，{link:al-aketh}奥拉凯斯{/link}已将其据为己有。传教士在村口接待新的皈依者，并给他们打上阿基尔的印记。风暴在它破败的房屋之间成形，那是教派的唤风者召唤下来的。正是在法拉斯的旅店里，{link:skypriest-aanders}天空祭司安德斯{/link}秘密接待了{link:high-priestess-lorthuna}大祭司洛苏娜{/link}，教派在那里谋划了对{link:shen-dar-village}辛达尔村{/link}和{link:west-pylon-watchtower}西部瞭望塔{/link}的双重打击。指挥官塞克拉斯本应领导第一场袭击。他没能活到那一天。]=],
		},
	},
})

Translate("zhCN", "windsong-lake", {
	title = "风歌湖",
	sections = {
		{
			title = "概述",
			text = [=[风歌湖位于{link:zephras-isle}泽弗拉斯{/link}的中部，在{link:razorfen-downs}高地{/link}与神殿之间。一种被称为风歌爬行蟹的螃蟹生活在湖岸以及汇入湖中的河流里，世界上别处都没有。每年只有几个星期可以捕捉它们。从前，这种螃蟹是运往{link:skyborne}申多雷{/link}其他岛屿的珍馐。{link:vanishing-of-the-wind-spirits}风之灵{/link}赠送的构造体曾在湖中拖网。当{link:anchor-pylons}锚定塔{/link}开始失效时，许多构造体沉到了湖底，有些至今仍躺在那里。]=],
		},
	},
})

Translate("zhCN", "west-pylon-watchtower", {
	title = "西锚定塔瞭望塔",
	aliases = { "西部瞭望塔" },
	sections = {
		{
			title = "概述",
			text = [=[西锚定塔瞭望塔守护着{link:shen-dar-highlands}辛达尔高地{/link}西南边缘的一座{link:anchor-pylons}锚定塔{/link}。{link:peacekeepers}维和者{/link}一直守着它，直到{link:al-aketh}奥拉凯斯{/link}到来。{link:skypriest-aanders}天空祭司安德斯{/link}领导了这次袭击，守卫者死在了他们的岗位上。其中有大长老{link:talaanis-shadowsong}塔兰尼斯·影歌{/link}的侄子，他的家族印戒在塔中被找到。天空祭司在那里对锚定塔做了什么，没有记载。{link:shadow-council}议会{/link}只知道，教派是冲着这座塔来的，而不是冲着塔里的士兵。]=],
		},
	},
})

Translate("zhCN", "valanaar", {
	title = "瓦兰纳尔",
	sections = {
		{
			title = "概述",
			text = [=[瓦兰纳尔是{link:zephras-isle}泽弗拉斯岛{/link}的港口与首要城市，建在岛的东南边缘。大长老{link:talaanis-shadowsong}塔兰尼斯·影歌{/link}在这里召开{link:shadow-council}议会{/link}，{link:valennia-stormfist}瓦伦妮娅·风暴之拳{/link}在同一座大厅里统领{link:peacekeepers}维和者{/link}。{link:windshapers}塑风者{/link}在城市中心附近有一座会所，{link:high-order}至高教团{/link}则在城市远端的东南侧另有一座。队长禁止他们在她的街道上公开争斗。{link:ruins-of-ban-aethal}班埃索尔{/link}的难民在城里等待消息。如今，破空船从瓦兰纳尔空港出发，穿越位面驶往{link:azeroth}艾泽拉斯{/link}：一艘驶向{link:mulgore}莫高雷{/link}，另一艘驶向{link:dalaran}达拉然{/link}。]=],
		},
	},
})

Translate("zhCN", "gustberry-lowlands", {
	title = "风莓低地",
	aliases = { "风莓田野" },
	sections = {
		{
			title = "概述",
			text = [=[风莓低地是{link:valanaar}瓦兰纳尔{/link}周围的农田，果园和开阔的田野物产丰饶。巨大的扑翼蝶在田野上空飘荡，烈风行者劫掠庄稼。拦路的盗匪在山丘中扎下小营地。城西一个洞穴里的尖啸兽变得胆大妄为，一位{link:high-order}至高教团{/link}的学者差点死在它们之中。当{link:al-aketh}奥拉凯斯{/link}向东部{link:anchor-pylons}锚定塔{/link}进军时，低地变成了战场，教派的治疗者和打手挤满了城北的田野。在瓦兰纳尔以西的岛屿边缘，{link:windshapers}塑风者{/link}守护着一座隐秘的火焰神龛。]=],
		},
	},
})

Translate("zhCN", "east-pylon-watchtower", {
	title = "东锚定塔瞭望塔",
	aliases = { "东部瞭望塔" },
	sections = {
		{
			title = "概述",
			text = [=[东锚定塔瞭望塔矗立在{link:valanaar}瓦兰纳尔{/link}城外，守护着离城市最近的{link:anchor-pylons}锚定塔{/link}。{link:al-aketh}奥拉凯斯{/link}在{link:commander-belguilos}指挥官贝尔吉洛斯{/link}的率领下大举进攻，她曾是一名{link:peacekeepers}和平卫士{/link}，教派称她为破坏者。{link:yorana-windyreed}约拉娜·风苇{/link}从城里带来一支援军并坚守下来，尽管她以为自己会死在那里。当贝尔吉洛斯倒下，进攻便瓦解了。{link:shadow-council}议会{/link}看到教派对西部和东部的瞭望塔都发动了袭击，终于明白它的目标是锚定塔本身。]=],
		},
	},
})

Translate("zhCN", "windfield-orchard", {
	title = "风野果园",
	sections = {
		{
			title = "概述",
			text = [=[风野果园在{link:valanaar}瓦兰纳尔{/link}以西的低地上种植风暴苹果。它属于阿尔瓦里昂和{link:aamelia-windfield}艾米莉亚·风野{/link}。一伙由重锤费劳率领的盗匪用武力抢走每次收成的一部分。阿尔瓦里昂身受重伤后，去城里雇人帮忙，他的妻子则留下来保卫他们的果树。果园里还立着一台{link:vanishing-of-the-wind-spirits}风之灵{/link}留下的古老旋风构造体，它已经损坏，喃喃自语。它一遍又一遍地问着同一个问题：它的用途是什么？]=],
		},
	},
})

Translate("zhCN", "shrine-of-akir", {
	title = "阿基尔神殿",
	sections = {
		{
			title = "概述",
			text = [=[阿基尔神殿耸立在{link:valanaar}瓦兰纳尔{/link}以北，俯瞰着岛东部的田野和瀑布。它是{link:al-aketh}奥拉凯斯{/link}的据点，也是{link:high-priestess-lorthuna}大祭司洛苏娜{/link}的居所。{link:high-order}至高教团{/link}的魔导师{link:belathaan-brightwish}贝拉桑·明愿{/link}曾来这里谈和平，并死在了这里。也是在这里，{link:valennia-stormfist}瓦伦妮娅·风暴之拳{/link}率领{link:peacekeepers}维和者{/link}、{link:windshapers}塑风者{/link}和至高教团发动了进攻。她的战士从正面进攻，她则带领两个组织从侧翼攀上，攻入内殿。双方都有许多人倒下。洛苏娜通过一道传送门逃往上方的尖塔。]=],
		},
	},
})

Translate("zhCN", "rohashi-spires", {
	title = "罗哈希尖塔",
	sections = {
		{
			title = "概述",
			text = [=[罗哈希尖塔漂浮在{link:shrine-of-akir}阿基尔神殿{/link}上方的开阔天空中，只能通过神殿里的一道传送门抵达。{link:high-priestess-lorthuna}洛苏娜{/link}在这里做了最后的抵抗。她不是来打破结界的，因为结界早已被打破。她是来点燃一座信标的。回应它的是东风之王{link:rohash}洛哈什{/link}。有那么一刻，精灵们独自面对{link:al-akir}风王{/link}的大军。随后{link:earthen-ring}大地之环{/link}的萨满祭司和{link:kirin-tor}肯瑞托{/link}的法师们赶到，这些尖塔成了{link:skyborne}天裔{/link}第一次遇见他们新盟友的地方。]=],
		},
	},
})

Translate("zhCN", "shadowgale-forest", {
	title = "影风森林",
	aliases = { "影风" },
	sections = {
		{
			title = "概述",
			text = [=[影风森林覆盖着{link:zephras-isle}泽弗拉斯{/link}的东北部，大多数{link:skyborne}申多雷{/link}认为这里闹鬼。他们没有说错。被称为空魂的苍白风灵在林间飘荡，它们最初是在{link:vanishing-of-the-wind-spirits}风之灵{/link}消失后出现的。教派通常避开这片森林，而这里的德鲁伊乐于助长这种恐惧。在东北方的一个洞穴里，夜爪德鲁伊守着他们的巢穴。{link:al-aketh}奥拉凯斯{/link}在德鲁伊自己人的引导下，毫无预警地袭击了那里。林间还住着一个多年没有和任何人说过话的隐士。]=],
		},
	},
})

Translate("zhCN", "ruins-of-ban-aethal", {
	title = "班埃索尔废墟",
	aliases = { "班埃索尔" },
	sections = {
		{
			title = "概述",
			text = [=[班埃索尔曾是{link:shadowgale-forest}影风森林{/link}深处的一个村庄，位于岛的东北边缘。一天夜里，毫无预警地，它脚下的土地开始坠入天空。村民们带着能带走的东西逃离，如今在{link:valanaar}瓦兰纳尔{/link}等待。有些人回去取自己的财物，再也没有回来。在废墟之间，幽灵般的灵魂聚集在一起，唱着一首奇异而哀伤的歌，仿佛被束缚在这个地方。据说有一条巨大的{link:elements}元素{/link}巨龙在那里沉睡。]=],
		},
	},
})

