			hint = "把叛教者携带的东西交给大长老。",
			text = [=[叛教者没来得及开口就死了，但在他的尸体下面有一块受损的记忆水晶。塔兰尼斯让{link:valennia-stormfist}瓦伦妮娅{/link}唤醒它。断断续续的声音飘了出来：是{link:high-priestess-lorthuna}洛苏娜{/link}，在谈论{link:anchor-pylons}锚定塔{/link}，以及必须倒下的结界。瓦伦妮娅想起{link:flight-from-eldre-thalas}沙尔南{/link}曾说过，锚定塔既是锚，也是结界，是抵御{link:skywall}天空之墙{/link}中其他存在的屏障。塔兰尼斯立刻明白了。教派想要把这座岛向它的{link:al-akir}风王{/link}敞开。]=],
		},
		{
			title = "泽弗拉斯的命运",
			hint = "告诉大长老在尖塔上得知的一切。",
			text = [=[尖塔之战后，两个组织的领袖带着同样严峻的消息来见塔兰尼斯。结界已经消失，这座岛在{link:al-akir}奥拉基尔{/link}自己的领域中暴露无遗。每个组织都打算到{link:azeroth}艾泽拉斯{/link}寻找答案，塔兰尼斯为两者都送上了祝福。他希望，无论他们找到什么，都能给{link:zephras-isle}泽弗拉斯{/link}带来它多年来所缺少的安定。]=],
		},
	},
	mentions = {
