		},
	},
	chapters = {
		{
			title = "锁孔",
			hint = "听听至高魔导师对至高教团的计划。",
			text = [=[艾拉德林把锁孔让他看到的东西告诉了他的组织里的年轻人。他的人民曾经逃离的土地，只是一个如今被称为{link:azeroth}艾泽拉斯{/link}的广阔世界的一部分。他的法师们在那里找到了朋友，一个与他们自己很相似的组织。他说，一些{link:skyborne}申多雷{/link}必须离开{link:skywall}天空之墙{/link}，找回他们的祖先失去的东西，并把它带回家，拯救这座岛。]=],
		},
		{
			title = "镀银的舌头",
			hint = "在得知使者的下场后回应至高魔导师。",
