		},
		{
			title = "驶向达拉然的破空船",
			hint = "从瓦兰纳尔乘船前往法师之城。",
			text = [=[艾拉德林原本打算成为他的人民中第一个踏上{link:azeroth}艾泽拉斯{/link}的人。教派改变了他的计划。眼下他留在{link:valanaar}瓦兰纳尔{/link}，先把年轻的魔导师们送往{link:dalaran}达拉然{/link}，他的一位法师在那里等着接待他们。]=],
