			title = "伟大的冒险",
			hint = "听听大天空先知对塑风者的计划。",
			text = [=[艾耶莎把她的发现告诉了年轻的{link:windshapers}塑风者{/link}。他们民族的摇篮{link:kalimdor}卡利姆多{/link}，如今是一个大得多的世界的一部分。那里的萨满祭司比{link:zephras-isle}泽弗拉斯{/link}上的任何人都更强大，他们对诸位面的了解或许能拯救这座岛。她请求强壮的年轻{link:skyborne}申多雷{/link}加入前往他们那里的远征。]=],
		},
		{
			title = "损坏的构造体",
			hint = "查明是谁偷走了瓦兰纳尔构造体的零件。",
			text = [=[{link:valanaar}瓦兰纳尔{/link}最后几台还能运转的构造体之一被发现零件被拆光了。线索指向{link:high-order}至高教团{/link}的魔导师{link:belathaan-brightwish}贝拉桑·明愿{/link}。在艾耶莎看来，这证明了她长久以来对魔导师们傲慢的指责。她传话说，只有至高教团的领袖亲自来找她，她才会回应他们的威胁。]=],
		},
		{
			title = "我昔日的姐妹",
			hint = "在神殿上方的尖塔上与大天空先知站在一起。",
			text = [=[在尖塔上，艾耶莎恳求{link:high-priestess-lorthuna}洛苏娜{/link}住手，警告说打破结界可能会毁灭他们所有人。洛苏娜嘲笑她是一个与{link:high-order}至高教团{/link}为伍的堕落姐妹。当东风之王到来时，{link:muln-earthfury}穆恩·地怒{/link}带着{link:earthen-ring}大地之环{/link}的萨满祭司们赶到了。艾耶莎在一场战斗之中第一次见到了他。]=],
		},
		{
			title = "先锋",
			hint = "从瓦兰纳尔乘船前往大地之环的土地。",
			text = [=[艾耶莎原本打算亲自前往{link:azeroth}艾泽拉斯{/link}。教派把她留在了{link:valanaar}瓦兰纳尔{/link}。她转而派出一小队年轻的{link:windshapers}塑风者{/link}作为她的先锋，前往{link:mulgore}莫高雷{/link}，{link:alaana-stormwalker}阿兰娜·风暴行者{/link}在那里等候。她已发誓，她的人民一定会找到拯救家园的办法。]=],
		},
	},
	mentions = {
		{ text = "大天空先知" },
		{ text = "坚决的回应" },
		{ text = "以血还血" },
		{ text = "为{link:zephras-isle}泽弗拉斯{/link}效力" },
		{ text = "{link:zephras-isle}泽弗拉斯{/link}的命运" },
		{ text = "接下来" },
	},
	bonds = {
		{ id = "muln-earthfury", name = "穆恩·地怒", note = "回应了她的大地之环萨满祭司" },
		{ id = "elaadrin-evengale", name = "艾拉德林·暮风", note = "她的对手，眼下是她的盟友" },
		{ id = "high-priestess-lorthuna", name = "大祭司洛苏娜", note = "曾是她在塑风者中的姐妹" },
		{ id = "illaya-amberwind", name = "伊莱娅·琥珀之风", note = "她的组织在辛达尔的长老" },
		{ id = "alaana-stormwalker", name = "阿兰娜·风暴行者", note = "在莫高雷等待她的先锋" },
		{ id = "talaanis-shadowsong", name = "塔兰尼斯·影歌", note = "泽弗拉斯岛的大长老" },
	},
})

Translate("zhCN", "al-akir", {
	title = "奥拉基尔",
	subtitle = "风王，天空之墙之主",
	found = "天空之墙无尽风暴中的某处",
	allegiance = "元素位面",
	aliases = { "风王奥拉基尔", "风王" },
	sections = {
		{
			title = "概述",
			text = [=[风王奥拉基尔是空气之主，{link:skywall}天空之墙{/link}的主人。他是四大{link:elements}元素{/link}领主之一，与火焰的{link:ragnar-thunderbrew}拉格纳{/link}罗斯、潮汐的耐普图隆和岩石的塞拉赞恩地位相当。风与风暴是他的仆从，空气元素是他的大军。没有任何凡人的编年史讲述过有谁站在他面前之后还能回来。]=],
		},
		{
			title = "意义",
			text = [=[对{link:elements}元素领主{/link}而言，凡人的民族无足轻重。风王并不知道{link:skyborne}申多雷{/link}的存在。一万年来，他自己领域中的灵魂用{link:anchor-pylons}锚定塔{/link}的结界把{link:zephras-isle}泽弗拉斯岛{/link}藏在他的视线之外，精灵们在他的领地中长大，却对他一无所知。抚养他们的灵魂不愿说出他的名字。当精灵们问起时，灵魂们便不安起来，岔开话题，告诉他们在自己的岛上无需害怕任何东西。一些申多雷开始怀疑他是否真的存在。另一些人用天视越过位面，瞥见了他的力量，并开始崇拜它。]=],
		},
		{
			title = "事迹",
			text = [=[• 在世界的最初时代，他与其他{link:elements}元素{/link}领主侍奉上古之神，直到泰坦的仆从把元素生物束缚在一个独立的领域中。
• 他率领一支由空气元素和诸风之王组成的大军统治{link:skywall}天空之墙{/link}。
• {link:al-aketh}奥拉凯斯{/link}崇拜他的名字，并自称他的信徒。
• 他的传教士警告说，任何以虚假借口接近他的信徒的人，都将感受到他的愤怒。
• 他的仆从{link:rohash}洛哈什{/link}夸口说，在天空之墙中，风王的军队无穷无尽。
• 对他到来的恐惧，如今驱使着{link:skyborne}申多雷{/link}的两个组织前往{link:azeroth}艾泽拉斯{/link}寻求帮助。]=],
		},
		{
			title = "未载",
			text = [=[这个时代的编年史没有描述风王的面容、他在{link:skywall}天空之墙{/link}中的王座，也没有描述他的意志。{link:skyborne}申多雷{/link}只能通过他们的灵魂的沉默和他的仆从的夸耀来了解他。]=],
		},
	},
	chapters = {
		{
			title = "风王的凝视",
			hint = "了解大地之环和肯瑞托告诉两个组织的关于风王的事。",
			text = [=[当{link:high-priestess-lorthuna}洛苏娜{/link}在{link:rohashi-spires}罗哈希尖塔{/link}上点燃她的信标时，东风之王{link:rohash}洛哈什{/link}回应了它。他惊讶于风王的领域中竟能存在这样一个地方，并称赞他那些“任性的兄弟”把它藏得如此之好。他保证他的主人会听说此事。{link:earthen-ring}大地之环{/link}的萨满祭司和{link:kirin-tor}肯瑞托{/link}的法师们把他们所知的关于{link:elements}元素{/link}领主的事告诉了精灵们。他们听到的内容让两个组织的领袖有充分的理由感到恐惧。在他自己的领地中，奥拉基尔随时可以毁灭他们。]=],
		},
	},
	mentions = {
		{ text = "下一步，一位长老称他为{link:skywall}天空之墙{/link}所谓的统治者" },
		{ text = "{link:falaath-village}法拉斯村{/link}，教派召唤人们侍奉他" },
	},
	bonds = {
		{ id = "rohash", name = "洛哈什", note = "东风之王，他的仆从" },
		{ id = "high-priestess-lorthuna", name = "大祭司洛苏娜", note = "以他之名点燃了信标" },
		{ id = "ayessa-dawnsinger", name = "艾耶莎·晨歌", note = "畏惧他的审判" },
	},
})

Translate("zhCN", "valennia-stormfist", {
	title = "瓦伦妮娅·风暴之拳",
	subtitle = "维和者的队长",
	found = "瓦兰纳尔的议会大厅",
	hint = "到瓦兰纳尔的议会大厅中寻找维和者的队长。",
	allegiance = "维和者 · 泽弗拉斯岛",
	aliases = { "瓦伦妮娅" },
	sections = {
		{
			title = "概述",
			text = [=[瓦伦妮娅·风暴之拳是{link:peacekeepers}维和者{/link}的队长，维和者是{link:zephras-isle}泽弗拉斯岛{/link}的民兵。她维持着{link:valanaar}瓦兰纳尔{/link}的秩序，禁止{link:windshapers}塑风者{/link}和{link:high-order}至高教团{/link}在她的街道上争斗。她直率而务实。很长一段时间里，她的维和者避免与教派公开开战。当这已不再可能时，她成了策划这场战争的人。]=],
		},
		{
			title = "意义",
			text = [=[瓦伦妮娅站在岛上两个争吵不休的组织与威胁着他们双方的教派之间。她看出，{link:windshapers}塑风者{/link}和{link:high-order}至高教团{/link}永远不会为了对方而团结。但他们或许会为了对抗一个更大的敌人而团结。她早在需要之前就准备好的进攻{link:shrine-of-akir}阿基尔神殿{/link}的计划，把三支力量一同带上了战场。]=],
		},
		{
			title = "事迹",
			text = [=[• 她从{link:valanaar}瓦兰纳尔{/link}统领{link:peacekeepers}维和者{/link}。
• 当教派进攻{link:east-pylon-watchtower}东部瞭望塔{/link}时，她派出了援军。
• 她唤醒了叛教者的记忆水晶，并想起{link:anchor-pylons}锚定塔{/link}同时也是结界。
• 她为进攻神殿赢得了两个组织的支持。
• 她攻入了{link:shrine-of-akir}阿基尔神殿{/link}的内殿。]=],
		},
	},
	chapters = {
		{
			title = "非常时期",
			hint = "把队长的计划送到两个组织的领袖那里。",
			text = [=[教派控制着岛上的大片地区，并认为{link:peacekeepers}维和者{/link}已被击败。瓦伦妮娅打算利用这份傲慢来对付它。在神殿正面制造一场牵制，再由一支由维和者、{link:windshapers}塑风者{/link}和魔导师组成的小队从侧翼攀上，或许就能抵达内殿，在那里了结{link:high-priestess-lorthuna}洛苏娜{/link}。两个组织都同意了。谁也没有原谅对方。]=],
		},
		{
			title = "内殿",
			hint = "跟随队长的部队进入神殿的中心。",
			text = [=[内殿中的战斗先是激烈，随后变得出奇地安静。瓦伦妮娅的部队守住了内殿，伤痕累累，人数锐减。{link:high-priestess-lorthuna}洛苏娜{/link}已通过一道传送门逃往上方的尖塔，两个组织的领袖追了上去。瓦伦妮娅伤得太重，无法跟随，便派其他人去帮助他们。]=],
		},
	},
	mentions = {
		{ text = "前往{link:valanaar}瓦兰纳尔{/link}" },
		{ text = "塔防" },
		{ text = "窃听" },
		{ text = "准备战斗" },
		{ text = "与{link:high-priestess-lorthuna}洛苏娜{/link}对质" },
	},
	bonds = {
		{ id = "talaanis-shadowsong", name = "塔兰尼斯·影歌", note = "她效力的大长老" },
		{ id = "constable-aonda", name = "治安官奥恩达", note = "维持辛达尔的治安" },
		{ id = "yorana-windyreed", name = "约拉娜·风苇", note = "她的副官" },
		{ id = "hyusaa-quickbreeze", name = "休萨·疾风", note = "她在神殿的副手" },
		{ id = "high-priestess-lorthuna", name = "大祭司洛苏娜", note = "她追猎的敌人" },
	},
})

Translate("zhCN", "aetheen-of-the-gales", {
	title = "烈风之艾希恩",
	subtitle = "泽弗拉斯岛的长老",
	found = "森达尔村",
	hint = "寻找在森达尔村观察年轻人的议会长老。",
	allegiance = "长老议会 · 泽弗拉斯岛",
	aliases = { "艾希恩" },
	sections = {
		{
			title = "概述",
			text = [=[烈风之艾希恩是{link:zephras-isle}泽弗拉斯岛{/link}长老{link:shadow-council}议会{/link}的成员。她来到{link:thendal-village}森达尔村{/link}解读{link:moonglade}林地{/link}中风的流向，并评判在那里成年的年轻{link:skyborne}申多雷{/link}。她先观察，后开口。等到一个年轻人见到她时，她已经对他们了解了很多。]=],
		},
		{
			title = "意义",
			text = [=[艾希恩是{link:shadow-council}议会{/link}注视下一代的眼睛。在这个岛上需要每一双能干的手的时代，由她决定哪些年轻人已准备好离开{link:moonglade}林地{/link}的庇护。她也是最早向他们明确说出危险的人之一：{link:al-aketh}奥拉凯斯{/link}，{link:skywall}天空之墙{/link}一位“所谓的”统治者的狂热信徒，其力量与野心与日俱增。]=],
		},
		{
			title = "事迹",
			text = [=[• 她为{link:shadow-council}议会{/link}解读{link:thendal-village}森达尔林地{/link}的风。
• 她派年轻人去对付乌瑟拉及其巢穴之母，以此考验他们。
• 她把他们派往南方受教派威胁的{link:shen-dar-village}辛达尔村{/link}，去找{link:constable-aonda}治安官奥恩达{/link}。
• 她派另一些人去向{link:kindal-moonweaver}辛达尔{/link}附近的一位流浪者学习荒野之道。]=],
		},
		{
			title = "未载",
			text = [=[关于艾希恩在这些日子之前的生活，记载甚少。她是否属于两个组织之一，她在{link:shadow-council}议会{/link}中任职了多久，都没有记载。]=],
		},
	},
	chapters = {
		{
			title = "下一步",
			hint = "通过长老的试炼，前往她派你去的地方。",
			text = [=[在{link:moonglade}林地{/link}以南的洞穴里，乌瑟拉变得饥饿而绝望，领头的是一头被游侠们称为乌尔萨纳的巢穴之母。艾希恩把年轻人派到那里，考验他们的决心。考验通过后，她并没有夸奖他们太久。她把他们派往南方，教派正在那里进逼{link:shen-dar-village}辛达尔村{/link}，并让他们说是她派他们去的。]=],
		},
	},
	mentions = {
		{ text = "烈风之艾希恩" },
		{ text = "邪恶的女族长" },
		{ text = "冒险者" },
	},
	bonds = {
		{ id = "rorian-the-dayseeker", name = "寻日者罗里安", note = "把年轻人送到她这里" },
		{ id = "constable-aonda", name = "治安官奥恩达", note = "用她的话说，一个好女人" },
		{ id = "talaanis-shadowsong", name = "塔兰尼斯·影歌", note = "她所在议会的大长老" },
	},
})

Translate("zhCN", "high-priestess-lorthuna", {
	title = "大祭司洛苏娜",
	subtitle = "奥拉凯斯的大祭司",
	found = "阿基尔神殿及其上方的尖塔",
	hint = "与风王教派的大祭司对决。",
	allegiance = "奥拉凯斯",
	aliases = { "洛苏娜" },
	sections = {
		{
			title = "概述",
			text = [=[大祭司洛苏娜领导着{link:al-aketh}奥拉凯斯{/link}，{link:zephras-isle}泽弗拉斯岛{/link}上崇拜{link:al-akir}奥拉基尔{/link}的教派。她曾是一名{link:windshapers}塑风者{/link}，是{link:ayessa-dawnsinger}艾耶莎·晨歌{/link}所在组织中的一位姐妹。如今她统治着{link:shrine-of-akir}阿基尔神殿{/link}，谈论着一项将把风王带到她的人民面前的伟大事业。她冷酷、狡猾而残忍，她的追随者自称她意志的工具。]=],
		},
		{
			title = "意义",
			text = [=[洛苏娜看到了她的人民没有看到的东西：{link:zephras-isle}泽弗拉斯{/link}的{link:anchor-pylons}锚定塔{/link}既是锚，也是结界。她把这个秘密变成了武器。她的教派夺取了{link:falaath-village}法拉斯村{/link}，袭击了锚定塔的瞭望塔，使结界倒下。无论她后来怎样，她的作为都无法挽回。泽弗拉斯如今暴露在它的{link:al-akir}风王{/link}面前。]=],
		},
		{
			title = "事迹",
			text = [=[• 她从{link:shrine-of-akir}阿基尔神殿{/link}向全岛派出劫掠者和布道者。
• 她在法拉斯会见了{link:skypriest-aanders}天空祭司安德斯{/link}，发动了对{link:kindal-moonweaver}辛达尔{/link}和{link:west-pylon-watchtower}西部瞭望塔{/link}的袭击。
• 她派人杀死了{link:high-order}至高教团{/link}的使者{link:belathaan-brightwish}贝拉桑·明愿{/link}，并把他的舌头送回了{link:valanaar}瓦兰纳尔{/link}。
• 她在{link:rohashi-spires}罗哈希尖塔{/link}上为{link:al-akir}风王{/link}的仆从点燃了一座信标。]=],
		},
	},
	chapters = {
		{
			title = "法拉斯的客人",
			hint = "查明教派对辛达尔高地的图谋。",
			text = [=[一个混入法拉斯信徒之中的新人被告知不要靠近旅店，天空祭司正在那里接待一位客人。那位客人就是洛苏娜。她的命令很简短。她还有别的事务，这只是她棋局中的一步。{link:skypriest-aanders}安德斯{/link}将夺取{link:west-pylon-watchtower}西部瞭望塔{/link}，塞克拉斯将夺取{link:shen-dar-village}辛达尔村{/link}。]=],
		},
		{
			title = "信标",
			hint = "跟随大祭司前往她的神殿上方的尖塔。",
			text = [=[在尖塔上，洛苏娜告诉她的敌人，他们来得太晚了。结界已经倒下好几天了。她正在点燃一座信标。当东风之王到来时，她向他致敬，请求作为他荣耀的传令者被带到{link:al-akir}风王{/link}面前。{link:rohash}洛哈什{/link}把她击到一旁，让她飞入了无尽的天空。]=],
		},
	},
	mentions = {
		{ text = "{link:al-aketh}奥拉凯斯{/link}暴徒" },
		{ text = "十倍复仇" },
		{ text = "教派的真正计划" },
	},
