Translate("zhCN", "windshapers", {
	title = "塑风者",
	aliases = { "塑风者" },
	sections = {
		{
			title = "概述",
			text = [=[塑风者是{link:skyborne}天裔{/link}的萨满祭司与先知。他们是最早获得{link:vanishing-of-the-wind-spirits}风之灵{/link}所赐天视的申多雷的后裔，天视是一种能看穿{link:elements}元素{/link}位面的力量。长久以来，他们一直是{link:zephras-isle}泽弗拉斯岛{/link}的精神向导。他们守护着岛上神圣的立石，照料灵魂留下的构造体和器具。]=],
		},
		{
			title = "他们的信条",
			text = [=[塑风者认为，他们的民族欠{link:vanishing-of-the-wind-spirits}风之灵{/link}一笔永远无法完全偿还的债。他们已发誓要找到灵魂，恢复旧日的传统。他们说，没有了灵魂，他们对{link:skywall}天空之墙{/link}中发生的事几乎一无所见。他们中的一些人担心，灵魂的离去是他们自己的过错。他们不信任{link:high-order}至高教团{/link}，称其为上层精灵傲慢的继承者，想要掌控本应尊崇之物。至高教团把升起的魔网线视为礼物，塑风者却把它们看作大地的伤口。]=],
		},
		{
			title = "当今",
			text = [=[自从灵魂离去，他们的魔法已经衰退，他们与{link:high-order}至高教团{/link}之间也有了血仇。他们的领袖，{link:ayessa-dawnsinger}大天空先知{/link}艾耶莎·晨歌，用天视搜寻诸位面，找到了{link:azeroth}艾泽拉斯{/link}的{link:earthen-ring}大地之环{/link}。通过大地之环，塑风者加入了{link:horde}部落{/link}。他们的先锋如今正从{link:valanaar}瓦兰纳尔{/link}驶往{link:mulgore}莫高雷{/link}。]=],
		},
	},
})

Translate("zhCN", "high-order", {
	title = "至高教团",
	sections = {
		{
			title = "概述",
			text = [=[至高教团是{link:skyborne}天裔{/link}的魔导师，埃德{link:farmer-ray}雷{/link}·萨拉斯上层精灵学者的后裔。他们自称上层精灵之道的守护者。在{link:skywall}天空之墙{/link}的一万年里，他们的许多奥术知识被遗忘，力量也随之衰退。他们打算把它找回来。]=],
		},
		{
			title = "他们的信条",
			text = [=[至高教团认为，{link:skyborne}申多雷{/link}把自己的命运交到变幻无常的灵魂手中，是犯了一个严重的错误。灵魂的消失证明了这一点。这个组织相信，灵魂曾经做到的事，可以用{red:highborne}上层精灵{/red}的魔法做到，这座岛可以自立。他们研究{link:zephras-isle}泽弗拉斯{/link}升起的魔网线和立石的{link:elements}元素{/link}魔法，不管{link:windshapers}塑风者{/link}怎么说。在塑风者看来，他们是多管闲事的人。在他们自己看来，他们是唯一愿意行动的人。]=],
		},
		{
			title = "当今",
			text = [=[至高魔导师{link:elaadrin-evengale}艾拉德林·暮风{/link}找到了一种窥视诸位面的方法，并发现{link:dalaran}达拉然{/link}的{link:kirin-tor}肯瑞托{/link}正在回望。通过肯瑞托，至高教团加入了{link:alliance}联盟{/link}。它年轻的魔导师们如今正从{link:valanaar}瓦兰纳尔{/link}驶往达拉然，去找回他们的祖先失去的知识。]=],
		},
	},
})

Translate("zhCN", "al-aketh", {
	title = "奥拉凯斯",
	aliases = { "奥拉凯斯教派", "奥拉基尔教派" },
	sections = {
		{
			title = "概述",
			text = [=[奥拉凯斯是一个崇拜风王{link:al-akir}奥拉基尔{/link}的{link:skyborne}申多雷{/link}教派。它的一些创立者用天视眺望{link:skywall}天空之墙{/link}，瞥见了其主人可怕的力量。受到那股力量的诱惑，他们背离了自己的民族，投身于他的侍奉。当{link:vanishing-of-the-wind-spirits}风之灵{/link}消失时，这个教派在随之而来的恐惧中崛起。]=],
		},
		{
			title = "他们的信条",
			text = [=[教派宣扬说，{link:skyborne}申多雷{/link}变得骄傲而懒散，把风的恩赐视为理所当然，灵魂因此离开了他们。只有忏悔和侍奉{link:al-akir}风王{/link}才能让风回来。它的传教士装作一个温和的信仰。剩下的事由它的打手、唤风者和刺客去做。它的许多成员曾是{link:windshapers}塑风者{/link}、{link:peacekeepers}维和者{/link}或德鲁伊，{link:ayessa-dawnsinger}艾耶莎·晨歌{/link}称这个教派是她自己的组织的黑暗镜像。]=],
		},
		{
			title = "当今",
			text = [=[在{link:high-priestess-lorthuna}大祭司洛苏娜{/link}的领导下，教派占据了{link:falaath-village}法拉斯村{/link}和{link:shrine-of-akir}阿基尔神殿{/link}，劫掠岛上的商队，并袭击{link:anchor-pylons}锚定塔{/link}的瞭望塔，以打破隐藏{link:zephras-isle}泽弗拉斯{/link}的结界。它的大祭司已经不在，它的神殿已被攻破，但它的目的已经达成。{link:al-akir}风王{/link}的仆从如今知道了泽弗拉斯在哪里。]=],
		},
	},
})

Translate("zhCN", "peacekeepers", {
	title = "维和者",
	aliases = { "和平卫士" },
	sections = {
		{
			title = "概述",
			text = [=[维和者是{link:zephras-isle}泽弗拉斯岛{/link}的民兵，也是{link:skyborne}天裔{/link}最接近军队的存在。他们听命于{link:valanaar}瓦兰纳尔{/link}的队长{link:valennia-stormfist}瓦伦妮娅·风暴之拳{/link}和长老{link:shadow-council}议会{/link}。他们的治安官维持着各村的秩序，他们的士兵驻守着守护{link:anchor-pylons}锚定塔{/link}的瞭望塔。]=],
		},
		{
			title = "当今",
			text = [=[长久以来，维和者一直避免与{link:al-aketh}奥拉凯斯{/link}公开开战，希望这个教派只会是个麻烦。这个希望在{link:shen-dar-village}辛达尔村{/link}和{link:anchor-pylons}锚定塔{/link}的瞭望塔破灭了。他们人数不多，却在全岛与教派作战，并领导了对{link:shrine-of-akir}阿基尔神殿{/link}的进攻。他们也站在{link:windshapers}塑风者{/link}与{link:high-order}至高教团{/link}之间，他们的队长不容许这两个组织在{link:valanaar}瓦兰纳尔{/link}争斗。并非所有人都保持了忠诚。如今被教派称为破坏者的{link:commander-belguilos}贝尔吉洛斯{/link}，曾经穿着他们的制服。坚守下来的人中，有{link:kindal-moonweaver}辛达尔{/link}的{link:constable-aonda}治安官奥恩达{/link}、{link:east-pylon-watchtower}东部瞭望塔{/link}的副官{link:yorana-windyreed}约拉娜·风苇{/link}，以及队长的副手{link:hyusaa-quickbreeze}休萨·疾风{/link}。]=],
		},
	},
})

Translate("zhCN", "anchor-pylons", {
	title = "锚定塔",
	aliases = { "锚定塔", "风之塔" },
	sections = {
		{
			title = "概述",
			text = [=[锚定塔是古老的{link:elements}元素{/link}魔法之塔，是{link:vanishing-of-the-wind-spirits}风之灵{/link}送给{link:skyborne}申多雷{/link}的礼物。它们把{link:zephras-isle}泽弗拉斯岛{/link}联结在一起，并把它固定在{link:skywall}天空之墙{/link}中的位置上。{link:peacekeepers}维和者{/link}的瞭望塔矗立在它们旁边，一座在西部{link:razorfen-downs}高地{/link}，一座在{link:valanaar}瓦兰纳尔{/link}城外。]=],
		},
		{
			title = "衰弱",
			text = [=[自从灵魂消失，锚定塔就变得不稳定了。它们的辉煌没有改变，也看不出任何损坏，但它们的魔法正在动摇。随着魔法减弱，岛的一些部分崩塌并坠入天空。{link:skyborne}申多雷{/link}如今靠风之石来满足日常所需，{link:high-order}至高教团{/link}则希望在锚定塔的魔法彻底失效之前掌握它。]=],
		},
		{
			title = "结界",
			text = [=[{link:skyborne}申多雷{/link}几乎遗忘了它们的第二个用途。锚定塔也是结界。它们保护这座岛免受{link:skywall}天空之墙{/link}中其他存在的注视。{link:flight-from-eldre-thalas}沙尔南{/link}曾经谈到过这一点，{link:al-aketh}奥拉凯斯{/link}也得知了它。他们袭击锚定塔以打破结界，并且成功了。{link:zephras-isle}泽弗拉斯{/link}仍在漂浮，但它已不再隐秘。]=],
		},
	},
})

Translate("zhCN", "vanishing-of-the-wind-spirits", {
	title = "风之灵的消失",
	aliases = { "风之灵" },
	sections = {
		{
			title = "概述",
			text = [=[数千年来，风之灵与{link:skyborne}申多雷{/link}一同生活在{link:zephras-isle}泽弗拉斯岛{/link}上，是他们的庇护者、导师和朋友。它们升起了这座岛，照料它的魔法，并赐予它的先知天视。然后，在几个世纪前，它们消失了。它们没有发出任何警告，泽弗拉斯上也没有人知道它们为何离去，去了哪里。]=],
		},
		{
			title = "随后发生的事",
			text = [=[岛上的魔法开始消退。{link:anchor-pylons}锚定塔{/link}动摇了。灵魂的构造体大多停止了运转。被称为空魂的奇异苍白灵魂出现在{link:shadowgale-forest}影风森林{/link}中。野兽变得狂野，较弱小的风之精灵一受惊扰就变得暴烈。与其他岛屿的联系中断了，整座整座的村庄坠入天空。每个派系都以自己的方式解读这一损失。{link:windshapers}塑风者{/link}希望找到灵魂，把它们召唤回家。{link:high-order}至高教团{/link}说精灵们绝不能再依赖它们。{link:al-aketh}奥拉凯斯{/link}宣扬说，灵魂抛弃了一个骄傲的民族，唯有{link:al-akir}风王{/link}仍在。]=],
		},
	},
})

Translate("zhCN", "flight-from-eldre-thalas", {
	title = "逃离埃德雷·萨拉斯",
	aliases = { "埃德雷·萨拉斯的叛乱", "沙尔南" },
	sections = {
		{
			title = "概述",
			text = [=[{link:skyborne}天裔{/link}起初是叛乱者。{link:war-of-the-ancients}上古战争{/link}之后，埃德{link:farmer-ray}雷{/link}·萨拉斯的{red:highborne}上层精灵{/red}失去了曾经滋养他们魔法的{link:well-of-eternity}永恒之井{/link}，埃德雷·萨拉斯是{link:feralas}菲拉斯{/link}的一座城市，如今被称为{red:dire-maul}厄运之槌{/red}。{red:tortheldrin}托塞德林{/red}王子试图用越来越黑暗的力量维系他们。他的一些子民已经见识过这种渴求会导致什么，他们不愿让{link:azshara}艾萨拉{/link}的错误重演。]=],
		},
		{
			title = "蒙面者",
			text = [=[叛乱者由一个只被称为沙尔南的人领导，意为蒙面者，他把自己的脸藏在一张毫无特征的{link:ginro-hearthkindle}金{/link}色面具后面。他的名字成了战斗的呐喊。通过破坏以及更激烈的手段，他的追随者妨碍了王子的水晶聚焦网络，一次又一次地让他蒙羞。在那些日子里，北方{link:night-elves}暗夜精灵{/link}的德鲁伊之道也在城中传播开来，王子斥之为卑贱之术。叛乱者在他的圣所中做了最后的抵抗。他们避免了最坏的结果，但他们中的大多数人都死了。]=],
		},
		{
			title = "逃亡",
			text = [=[幸存者向西逃亡，王子的船队紧随其后。在大海的另一边，他们找到了一片由古老灵魂统治的土地，并在那里与风缔结了盟约。灵魂们把这片土地升入{link:skywall}天空之墙{/link}，流亡者们成了{link:skyborne}申多雷{/link}，隐秘之民。后来，沙尔南放下了他的统治权，把它交给了一个由他的人民推选的{link:shadow-council}议会{/link}。]=],
		},
	},
})
